package com.ftk.tpip.control.api.catalog;
import com.ftk.tpip.catalog.domain.model.OperationStatus;import com.ftk.tpip.control.application.catalog.CanonicalOperationApplicationService;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import java.net.URI;import org.springframework.http.ResponseEntity;import org.springframework.validation.annotation.Validated;import org.springframework.web.bind.annotation.*;
@Validated @RestController @RequestMapping("/control/v1/operations")
public class CanonicalOperationController{private final CanonicalOperationApplicationService service;public CanonicalOperationController(CanonicalOperationApplicationService service){this.service=service;}
@PostMapping public ResponseEntity<CanonicalOperationResponse> create(@Valid @RequestBody CreateCanonicalOperationRequest r,@RequestHeader("X-Operator") @NotBlank @Size(max=100) String actor){var o=service.create(r.capabilityId(),r.operationCode(),r.operationName(),r.description(),r.invocationMode(),r.idempotencyClass(),r.dataClassification(),r.ownerCode(),actor);return ResponseEntity.created(URI.create("/control/v1/operations/"+o.id())).body(CanonicalOperationResponse.from(o));}
@GetMapping("/{id}") public CanonicalOperationResponse get(@PathVariable @Min(1) long id){return CanonicalOperationResponse.from(service.get(id));}
@GetMapping public CanonicalOperationPageResponse list(@RequestParam(required=false) @Min(1) Long capabilityId,@RequestParam(required=false) String keyword,@RequestParam(required=false) OperationStatus status,@RequestParam(defaultValue="0") @Min(0) int page,@RequestParam(defaultValue="20") @Min(1) @Max(200) int size){return CanonicalOperationPageResponse.from(service.findAll(capabilityId,keyword,status,page,size));}
@PutMapping("/{id}") public CanonicalOperationResponse update(@PathVariable @Min(1) long id,@Valid @RequestBody UpdateCanonicalOperationRequest r,@RequestHeader("X-Operator") @NotBlank @Size(max=100) String actor){return CanonicalOperationResponse.from(service.update(id,r.operationName(),r.description(),r.invocationMode(),r.idempotencyClass(),r.dataClassification(),r.ownerCode(),r.status(),r.rowVersion(),actor));}}
